import subprocess, sys, itertools, string
BIN='/workspace/executable'
def probe(words, extra=None):
    """returns dict word->output for words that changed"""
    res={}
    B=4000
    for i in range(0,len(words),B):
        chunk=words[i:i+B]
        inp='\n'.join(chunk)+'\n'
        cmd=[BIN,'-g','.*']+(extra or [])
        out=subprocess.run(cmd,input=inp,capture_output=True,text=True).stdout.rstrip('\n').split('\n')
        for w,o in zip(chunk,out):
            if o!=w: res[w]=o
    return res
if __name__=='__main__':
    import time
    t=time.time()
    letters=string.ascii_lowercase
    prefs=['']+list(letters)+[a+b for a in letters for b in letters]
    suf=prefs
    dig={'ss':['ss','Ss','sS','SS'],'ue':['ue','Ue','uE','UE'],'ae':['ae','Ae','aE','AE'],'oe':['oe','Oe','oE','OE']}
    cands=[]
    for d,vs in dig.items():
        for v in vs:
            for p in prefs:
                for s in suf:
                    cands.append(p+v+s)
    print(len(cands),'candidates')
    r=probe(cands)
    print(time.time()-t,'sec; found',len(r))
    for k in sorted(r): print(f"  {k} -> {r[k]}")
PY
