def probe(words):
    res={}
    B=6000
    for i in range(0,len(words),B):
        c=words[i:i+B]
        out=subprocess.run(['/workspace/executable','-g','.*'],input='\n'.join(c)+'\n',capture_output=True,text=True).stdout.rstrip('\n').split('\n')
        for w,o in zip(c,out):
            if o!=w: res[w]=o
    return res
for w in ['masses','gruesse','aSSab','bruecke']:
    variants=[''.join(t) for t in itertools.product(*[(c.lower(),c.upper()) for c in w])]
    r=probe(variants)
    print(w, 'variants:', len(variants), 'transformed:', len(r))
    print('   ', sorted(r)[:12], '...' if len(r)>12 else '')
PY"}

