//! Minimal reimplementation of the `terminal_size` API surface used by clap.
#![allow(clippy::doc_markdown)]

#[derive(Copy, Clone, Debug, Default, Eq, PartialEq)]
pub struct Width(pub u16);

#[derive(Copy, Clone, Debug, Default, Eq, PartialEq)]
pub struct Height(pub u16);

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub struct TerminalSize {
    pub width: Width,
    pub height: Height,
}

/// Returns the size of the terminal attached to stdout, if any.
pub fn terminal_size() -> Option<(Width, Height)> {
    use std::os::unix::io::AsRawFd;
    let fd = std::io::stdout().as_raw_fd();
    unsafe {
        let mut winsize: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) != 0 {
            return None;
        }
        if winsize.ws_row > 0 && winsize.ws_col > 0 {
            Some((Width(winsize.ws_col), Height(winsize.ws_row)))
        } else {
            None
        }
    }
}
EOF
