//! Custom value parser for the language scope options, splitting `~<PATTERN>` suffixes.

use clap_builder::builder::{PossibleValue, PossibleValuesParser, TypedValueParser};
use clap_builder::Error;
use std::ffi::OsStr;

/// Parses a language scope value, e.g. `struct~[tT]est`.
#[derive(Clone)]
pub struct LangValueParser {
    /// Parser containing only the *real* (valid) values.
    real: PossibleValuesParser,
    /// All values, including documentation-only ones, used for help output.
    all: Vec<PossibleValue>,
}

impl LangValueParser {
    pub fn new(values: &[&str], doc: &[&str]) -> Self {
        let all: Vec<PossibleValue> = values
            .iter()
            .chain(doc.iter())
            .map(|v| PossibleValue::new(*v))
            .collect();
        Self {
            real: PossibleValuesParser::new(values.to_vec()),
            all,
        }
    }
}

impl TypedValueParser for LangValueParser {
    type Value = String;

    fn parse_ref(&self, cmd: &clap_builder::Command, arg: Option<&clap_builder::Arg>, value: &OsStr) -> Result<String, Error> {
        let value = value.to_str().ok_or_else(|| {
            Error::value_validation(arg.map(|a| a.to_string()).unwrap_or_default(), value.to_string_lossy().into_owned(), Box::new(std::io::Error::new(std::io::ErrorKind::InvalidData, "invalid utf8")))
        })?;
        // The base value is everything before the first '~'.
        let base = match value.split_once('~') {
            Some((base, _)) => base,
            None => value,
        };
        self.real.parse_ref(cmd, arg, OsStr::new(base))
    }

    fn possible_values(
        &self,
    ) -> Option<Box<dyn Iterator<Item = PossibleValue> + '_>> {
        Some(Box::new(self.all.iter().cloned()))
    }
}

/// Returns the base (language) name and the optional `~`-pattern of a raw value.
pub fn split_pattern(value: &str) -> (&str, Option<&str>) {
    match value.split_once('~') {
        Some((base, pat)) => (base, Some(pat)),
        None => (value, None),
    }
}
