//! Action implementations.

/// Symbol substitution table (longest first).
pub const SYMBOLS: &[(&str, &str)] = &[
    ("-->", "⟶"),
    ("<--", "⟵"),
    ("<->", "↔"),
    ("---", "—"),
    ("!=", "≠"),
    ("<=", "≤"),
    (">=", "≥"),
    ("->", "→"),
    ("<-", "←"),
    ("=>", "⇒"),
    ("--", "–"),
];

pub const SYMBOLS_REVERSE: &[(&str, &str)] = &[
    ("⟶", "-->"),
    ("⟵", "<--"),
    ("↔", "<->"),
    ("—", "---"),
    ("≠", "!="),
    ("≤", "<="),
    ("≥", ">="),
    ("→", "->"),
    ("←", "<-"),
    ("⇒", "=>"),
    ("–", "--"),
];

/// Substitute all longest-first occurrences of the table in `input`.
pub fn substitute(input: &str, table: &[(&str, &str)]) -> String {
    let mut out = String::with_capacity(input.len());
    let bytes = input;
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let rest: String = chars[i..].iter().collect();
        let mut matched = false;
        for (from, to) in table {
            if rest.starts_with(from) {
                out.push_str(to);
                i += from.chars().count();
                matched = true;
                break;
            }
        }
        if !matched {
            out.push(chars[i]);
            i += 1;
        }
    }
    let _ = bytes;
    out
}

/// Uppercase.
pub fn upper(input: &str) -> String {
    input.to_uppercase()
}

/// Lowercase.
pub fn lower(input: &str) -> String {
    input.to_lowercase()
}

/// Titlecase, mirroring the observed behaviour:
/// transform a word when it contains no uppercase letters, or when the whole
/// scope contains no lowercase letters at all.
pub fn titlecase(input: &str) -> String {
    use unicode_segmentation::UnicodeSegmentation;
    let has_lower = input.chars().any(|c| c.is_lowercase());
    let mut out = String::with_capacity(input.len());
    for word in input.split_word_bounds() {
        if word.is_empty() {
            continue;
        }
