    PRECOMPOSED
        .iter()
        .find(|(cp, _)| *cp == c as u32)
        .map(|(_, s)| *s)
}

/// German digraph -> Unicode substitutions, mirroring observed behaviour:
/// the case of the *first* character of the digraph decides the case of the output.
const GERMAN_SUBS: &[(char, char, char)] = &[
    ('a', 'e', 'ä'),
    ('A', 'e', 'Ä'),
    ('o', 'e', 'ö'),
    ('O', 'e', 'Ö'),
    ('u', 'e', 'ü'),
    ('U', 'e', 'Ü'),
    ('s', 's', 'ß'),
    ('S', 's', 'ẞ'),
];

pub fn german_substitute(input: &str) -> String {
    let chars: Vec<char> = input.chars().collect();
    let mut out = String::with_capacity(input.len());
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        let mut matched = false;
        for (a, b, to) in GERMAN_SUBS {
            if c == *a && i + 1 < chars.len() && chars[i + 1] == *b {
                out.push(*to);
                i += 2;
                matched = true;
                break;
            }
        }
        if !matched {
            out.push(c);
            i += 1;
        }
    }
    out
}

/// Expand `$1` / `$NAME` placeholders in the replacement text.
pub fn expand_replacement(
    replacement: &str,
    text: &str,
    group_names: &[Option<&str>],
    group_values: &[Option<&str>],
) -> String {
    let chars: Vec<char> = replacement.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() && chars[i + 1] == '$' {
            i += 2;
            continue;
        }
        if c == '$' {
            let mut j = i + 1;
            let mut name = String::new();
            if j < chars.len() && chars[j] == '{' {
                j += 1;
                while j < chars.len() && chars[j] != '}' {
                    name.push(chars[j]);
                    j += 1;
                }
                if j < chars.len() {
                    j += 1;
                }
            } else {
                while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '_') {
                    name.push(chars[j]);
                    j += 1;
                }
            }
            if !name.is_empty() {
                let value = if let Ok(idx) = name.parse::<usize>() {
                    group_values.get(idx).and_then(|v| *v).unwrap_or("")
                } else {
                    group_names
                        .iter()
                        .zip(group_values.iter())
                        .find(|(n, _)| **n == Some(name.as_str()))
                        .and_then(|(_, v)| *v)
                        .unwrap_or("")
                };
                out.push_str(value);
                i = j;
                continue;
            }
            out.push('$');
            i += 1;
            continue;
        }
        out.push(c);
        i += 1;
    }
    let _ = text;
    out
}
