//! Shared helpers used by the per-language construct finders.

/// Byte offsets of every line start.
pub fn line_starts(source: &str) -> Vec<usize> {
    std::iter::once(0)
        .chain(
            source
                .char_indices()
                .filter(|(_, c)| *c == '\n')
                .map(|(i, _)| i + 1),
        )
        .collect()
}

/// Finds string literal ranges (contents only) for common quote styles.
pub fn string_contents(source: &str) -> Vec<usize> {
    let mut ranges = Vec::new();
    let b = source.as_bytes();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == b'\\' {
            i += 2;
            continue;
        }
        // Triple-quoted strings.
        let triple: &[u8] = if c == b'"' { b"\"\"\"" } else if c == b'\'' { b"'''" } else { b"" };
        if !triple.is_empty() && source[i..].starts_with(triple) {
            let start = i + 3;
            if let Some(rel) = source[start..].find(triple) {
                ranges.push((start, start + rel));
                i = start + rel + 3;
                continue;
            }
        }
        let quote = if c == b'"' || c == b'\'' { c } else { 0 };
        if quote != 0 {
            let start = i + 1;
            let mut j = start;
            while j < b.len() {
                if b[j] == b'\\' {
                    j += 2;
                    continue;
                }
                if b[j] == quote {
                    break;
                }
                if b[j] == b'\n' {
                    break;
                }
                j += 1;
            }
            if j < b.len() && b[j] == quote {
                ranges.push((start, j));
                i = j + 1;
                continue;
            }
        }
        i += 1;
    }
    ranges
}

/// Finds line comments starting with `prefix` and block comments `open`/`close`.
pub fn comments(source: &str, prefixes: &[&str], open: &str, close: &str) -> Vec<usize> {
    let mut ranges = Vec::new();
    for (idx, _) in source.match_indices(open) {
        if let Some(rel) = source[idx + open.len()..].find(close) {
            ranges.push((idx, idx + open.len() + rel + close.len()));
        }
    }
    for prefix in prefixes {
        for (idx, _) in source.match_indices(prefix) {
            let end = source[idx..].find('\n').map(|p| idx + p).unwrap_or(source.len());
            ranges.push((idx, end));
        }
    }
    ranges.sort();
    ranges
}

/// Ranges of identifiers matching a simple "word" definition of the language.
pub fn identifiers(source: &str, word_chars: impl Fn(char) -> bool + Copy) -> Vec<usize> {
    let mut ranges = Vec::new();
    let mut start: Option<usize> = None;
    for (i, c) in source.char_indices() {
        if word_chars(c) {
            if start.is_none() {
                start = Some(i);
            }
        } else if let Some(s) = start.take() {
            ranges.push((s, i));
        }
    }
    if let Some(s) = start {
        ranges.push((s, source.len()));
    }
    ranges
}

/// Ranges of whole words (used to filter identifiers by surrounding characters).
pub fn whole_words(source: &str, word_chars: impl Fn(char) -> bool + Copy) -> Vec<usize> {
    let mut out = Vec::new();
    for (s, e) in identifiers(source, word_chars) {
        let before_ok = s == 0 || {
            let prev = source[..s].chars().next_back().unwrap();
            !word_chars(prev)
        };
        let after_ok = e == source.len() || {
            let next = source[e..].chars().next().unwrap();
            !word_chars(next)
        };
        if before_ok && after_ok {
            out.push((s, e));
        }
    }
    out
}

pub trait NextBack {
    fn next_back(&self) -> Option<char>;
}

impl NextBack for std::str::Chars<'_> {
    fn next_back(&self) -> Option<char> {
        let s: String = self.clone().collect();
        s.chars().last()
    }
}

/// Merges overlapping/adjacent ranges.
pub fn merge(mut ranges: Vec<usize>) -> Vec<usize> {
    ranges.sort();
    let mut out: Vec<usize> = Vec::new();
    for (s, e) in ranges {
        if let Some(last) = out.last_mut() {
            if s <= last.1 {
                last.1 = std::cmp::max(last.1, e);
                continue;
            }
        }
        out.push((s, e));
    }
    out
}

/// Expands a range to whole lines.
pub fn to_lines(source: &str, start: usize, end: usize) -> usize {
    let s = source[..start].rfind('\n').map(|p| p + 1).unwrap_or(0);
    let e = source[end..].find('\n').map(|p| end + p + 1).unwrap_or(source.len());
    (s, e)
}

/// Block construct: from a line starting with `keyword` to a line containing only `closer`.
pub fn block_by_indent(
    source: &str,
    keyword: &str,
    prefixes: &[&str],
    dedent_chars: &[char],
) -> Vec<usize> {
    let mut out = Vec::new();
    for (line_no, line) in crate::languages::common::lines(source) {
        let trimmed = line.trim();
        let is_start = keyword
            .split(' ')
            .all(|k| trimmed.starts_with(k))
            || (keyword.ends_with(':') && trimmed.starts_with(keyword));
        if !is_start {
            continue;
        }
        let indent = line.len() - line.trim_start().len();
        // find the end: last line of the block
        let mut end_line = line_no;
        for (n, l) in crate::languages::common::lines(source) {
            if n < line_no {
                continue;
            }
            if n == line_no {
                end_line = n;
                continue;
            }
            if l.trim().is_empty() {
                continue;
            }
            let ind = l.len() - l.trim_start().len();
            if ind > indent {
                end_line = n;
            } else {
                break;
            }
        }
        let start = line_starts_of(source, line_no);
        let end = line_starts_of(source, end_line + 1).unwrap_or(source.len());
        let (s, e) = (start, end);
        let _ = dedent_chars;
        let _ = prefixes;
        out.push((s, e));
    }
    out
}

pub fn lines(source: &str) -> Vec<(usize, &str)> {
    let mut out = Vec::new();
    let mut start = 0;
    for (i, c) in source.char_indices() {
        if c == '\n' {
            out.push((out.len(), &source[start..i]));
            start = i + 1;
        }
    }
    out.push((out.len(), &source[start..]));
    out
}

pub fn line_starts_of(source: &str, line_no: usize) -> Option<usize> {
    let mut pos = 0;
    for n in 0..line_no {
        if n > 0 {
            pos = source[pos..].find('\n')? + 1;
        }
    }
    Some(pos)
}
RSEOF
echo ok"}

