//! Language scope plumbing. Construct finders are minimal for now.

/// Byte ranges of interest.
pub type Range = (usize, usize);

/// File extensions associated with each language.
pub fn extensions(lang: &str) -> &'static [&'static str] {
    match lang {
        "python" => &["py"],
        "rust" => &["rs"],
        "go" => &["go"],
        "typescript" => &["ts", "tsx"],
        "csharp" => &["cs"],
        "c" => &["c", "h"],
        "hcl" => &["tf", "hcl"],
        _ => &[],
    }
}

#[derive(Debug, Default)]
pub struct LanguageScopes {
    pub c: Vec<String>,
    pub csharp: Vec<String>,
    pub go: Vec<String>,
    pub hcl: Vec<String>,
    pub python: Vec<String>,
    pub rust: Vec<String>,
    pub typescript: Vec<String>,
}

impl LanguageScopes {
    pub fn is_empty(&self) -> bool {
        self.c.is_empty()
            && self.csharp.is_empty()
            && self.go.is_empty()
            && self.hcl.is_empty()
            && self.python.is_empty()
            && self.rust.is_empty()
            && self.typescript.is_empty()
    }
    pub fn languages(&self) -> Vec<&'static str> {
        let mut v = Vec::new();
        if !self.c.is_empty() { v.push("c"); }
        if !self.csharp.is_empty() { v.push("csharp"); }
        if !self.go.is_empty() { v.push("go"); }
        if !self.hcl.is_empty() { v.push("hcl"); }
        if !self.python.is_empty() { v.push("python"); }
        if !self.rust.is_empty() { v.push("rust"); }
        if !self.typescript.is_empty() { v.push("typescript"); }
        v
    }
}

/// Merges overlapping ranges.
pub fn merge(mut ranges: Vec<Range>) -> Vec<Range> {
    ranges.sort();
    let mut out: Vec<Range> = Vec::new();
    for (s, e) in ranges {
        if let Some(last) = out.last_mut() {
            if s <= last.1 {
                last.1 = std::cmp::max(last.1, e);
                continue;
            }
        }
        out.push((s, e));
    }
    out
}

/// Computes ranges for a language scope value. Returns empty for unimplemented ones.
pub fn ranges_for(lang: &str, value: &str, source: &str) -> Vec<Range> {
    match lang {
        "python" => python::find(value, source),
        "rust" => rust::find(value, source),
        "go" => go::find(value, source),
        "typescript" => typescript::find(value, source),
        "csharp" => csharp::find(value, source),
        "c" => c::find(value, source),
        "hcl" => hcl::find(value, source),
        _ => vec![],
    }
}

pub mod common;
pub mod python;
pub mod rust;
pub mod go;
pub mod typescript;
pub mod csharp;
pub mod c;
pub mod hcl;
