//! Core processing engine: stdin and file-tree modes.

use crate::actions;
use crate::languages;

/// A scope: either "in scope" (transformed) or "out of scope" (kept verbatim).
#[derive(Debug, Clone)]
pub enum RWScope {
    In(String, Option<String>),
    Out(String),
}

/// Result of scoping a piece of text.
pub struct View {
    pub scopes: Vec<RWScope>,
    pub text: String,
}

/// Explodes `text` by applying the regex scope, producing in/out scopes.
pub fn explode(pattern: Option<&fancy_regex::Regex>, text: &str) -> Vec<(usize, usize, Option<Vec<String>>)> {
    let mut found = Vec::new();
    if let Some(re) = pattern {
        let mut cursor = 0;
        while let Ok(Some(caps)) = re.captures_from_pos(text, cursor) {
            let m = caps.get(0).unwrap();
            if m.start() == m.end() {
                // zero-width matches are skipped entirely
                if m.start() >= text.len() {
                    break;
                }
                cursor = m.end() + 1;
                continue;
            }
            let groups: Vec<String> = (0..caps.len())
                .map(|i| caps.get(i).map(|c| c.as_str().to_string()).unwrap_or_default())
                .collect();
            found.push((m.start(), m.end(), Some(groups)));
            cursor = m.end();
        }
    } else {
        found.push((0, text.len(), None));
    }
    languages::merge(found.into_iter().map(|(s, e, g)| (s, e, g))).collect::<Vec<_>>().into_iter().map(|(s,e,g)| (s,e,g)).collect()
}

pub fn run() -> i32 {
    let mut code = 0;
    let _ = &mut code;
    code
}
